module.exports = [
{ e: "🔬", art: { b: "🔬", s: ["💉", "🐍", "🛩️", "🧪"], c: ["#0B3A3A", "#2C8A8A"] },
pt: { h: "Leo tomou uma vacina e foi muito corajoso. Na volta, o vovô contou que um brasileiro ajudou a acabar com doenças terríveis no Rio de Janeiro, há mais de cem anos. “E outro brasileiro voou num avião em Paris”, acrescentou. Nina quis saber tudo sobre esses cientistas.", t: "Cientistas e inventores brasileiros", f: "O Brasil tem cientistas e inventores muito importantes. Oswaldo Cruz combateu doenças como a febre amarela, Carlos Chagas descobriu uma doença inteira e Vital Brazil criou soros contra picadas de cobra. E Santos-Dumont voou com o 14-Bis em Paris, em 1906.", x: "Carlos Chagas fez algo raríssimo: descobriu sozinho o micróbio, o inseto transmissor e a doença, que hoje leva o seu nome, a doença de Chagas!", s: ["O Instituto Butantan, em São Paulo, fundado por Vital Brazil, produz soros e vacinas até hoje.", "A Fiocruz, no Rio de Janeiro, foi criada a partir do trabalho de Oswaldo Cruz.", "Santos-Dumont também popularizou o relógio de pulso, para ver as horas sem soltar os comandos do avião."], ex: { t: "Helicóptero de papel", m: "uma tira de papel (uns 5 x 20 cm), tesoura, um clipe", p: ["Corte a tira ao meio no comprimento, só até a metade, formando duas “asas”.", "Dobre uma asa para a frente e outra para trás, e prenda o clipe na ponta de baixo.", "Solte de um lugar alto: ele gira e desce devagar! O ar empurra as asas, como nas máquinas voadoras."] }, at: "Cartão de cientista", m: "cartolina, lápis de cor", p: ["Escolha um dos cientistas de hoje.", "Faça um cartão com o desenho dele, o nome e a sua maior descoberta.", "Faça um cartão para você também: que descoberta você gostaria de fazer?"], q: "Que problema do mundo você gostaria de resolver com uma invenção?" },
en: { h: "Leo got a vaccine and was very brave. On the way home, Grandpa told him that a Brazilian helped wipe out terrible diseases in Rio de Janeiro more than a hundred years ago. “And another Brazilian flew an airplane in Paris,” he added. Nina wanted to know everything about these scientists.", t: "Brazilian scientists and inventors", f: "Brazil has very important scientists and inventors. Oswaldo Cruz fought diseases like yellow fever, Carlos Chagas discovered an entire disease and Vital Brazil created antivenoms for snakebites. And Santos-Dumont flew his 14-Bis plane in Paris in 1906.", x: "Carlos Chagas did something extremely rare: on his own, he discovered the germ, the insect that spreads it and the disease, which now bears his name, Chagas disease!", s: ["The Butantan Institute in São Paulo, founded by Vital Brazil, still makes antivenoms and vaccines today.", "Fiocruz, in Rio de Janeiro, grew out of Oswaldo Cruz's work.", "Santos-Dumont also helped make the wristwatch popular, so he could check the time without letting go of the controls."], ex: { t: "Paper helicopter", m: "a strip of paper (about 5 x 20 cm, or 2 x 8 inches), scissors, a paper clip", p: ["Cut the strip lengthwise down the middle, only halfway, to make two “wings.”", "Fold one wing forward and the other back, and clip the paper clip to the bottom end.", "Drop it from up high: it spins and floats down slowly! The air pushes the wings, like in flying machines."] }, at: "Scientist card", m: "poster board, colored pencils", p: ["Choose one of today's scientists.", "Make a card with a drawing of them, their name and their biggest discovery.", "Make a card for yourself too: what discovery would you like to make?"], q: "What world problem would you like to solve with an invention?" },
es: { h: "Leo se puso una vacuna y fue muy valiente. A la vuelta, el abuelo le contó que un brasileño ayudó a acabar con enfermedades terribles en Río de Janeiro hace más de cien años. “Y otro brasileño voló en un avión en París”, agregó. Nina quiso saber todo sobre esos científicos.", t: "Científicos e inventores brasileños", f: "Brasil tiene científicos e inventores muy importantes. Oswaldo Cruz combatió enfermedades como la fiebre amarilla, Carlos Chagas descubrió una enfermedad entera y Vital Brazil creó sueros contra las mordeduras de serpiente. Y Santos-Dumont voló con el 14-Bis en París, en 1906.", x: "¡Carlos Chagas hizo algo rarísimo: descubrió él solo el microbio, el insecto que lo transmite y la enfermedad, que hoy lleva su nombre, la enfermedad de Chagas!", s: ["El Instituto Butantan, en São Paulo, fundado por Vital Brazil, produce sueros y vacunas hasta hoy.", "La Fiocruz, en Río de Janeiro, nació del trabajo de Oswaldo Cruz.", "Santos-Dumont también ayudó a popularizar el reloj de pulsera, para ver la hora sin soltar los mandos."], ex: { t: "Helicóptero de papel", m: "una tira de papel (unos 5 x 20 cm), tijera, un clip", p: ["Corta la tira a lo largo por el medio, solo hasta la mitad, formando dos “alas”.", "Dobla un ala hacia adelante y la otra hacia atrás, y pon el clip en la punta de abajo.", "Suéltalo desde un lugar alto: ¡gira y baja despacio! El aire empuja las alas, como en las máquinas voladoras."] }, at: "Tarjeta de científico", m: "cartulina, lápices de colores", p: ["Elige a uno de los científicos de hoy.", "Haz una tarjeta con su dibujo, su nombre y su mayor descubrimiento.", "Haz una tarjeta para ti también: ¿qué descubrimiento te gustaría hacer?"], q: "¿Qué problema del mundo te gustaría resolver con un invento?" } },

{ e: "🎨", art: { b: "🎨", s: ["🌵", "☀️", "🖌️", "🖼️"], c: ["#5A2A0B", "#E09A2C"] },
pt: { h: "Nina desenhou uma pessoa com o pé gigante e a cabeça pequenininha, e Leo riu do desenho. O vovô pegou um livro e mostrou uma pintura famosa muito parecida. “Uma artista brasileira pintou assim de propósito”, disse. “E o quadro virou um dos mais importantes do Brasil.”", t: "A arte moderna brasileira", f: "Em 1922, um grupo de artistas fez a Semana de Arte Moderna, em São Paulo. Eles queriam criar uma arte com cara de Brasil, usando cores fortes, formas novas e temas do povo brasileiro, em vez de só copiar a Europa.", x: "O quadro Abaporu, pintado por Tarsila do Amaral em 1928, mostra uma figura de pé enorme e cabeça pequena. O nome vem do tupi e quer dizer algo como “homem que come”!", s: ["Tarsila usava cores vivas, como rosa, azul, amarelo e verde, inspiradas no interior do Brasil.", "Anita Malfatti fez uma exposição em 1917 que assustou muita gente por ser tão diferente.", "Candido Portinari pintou trabalhadores, crianças brincando e os painéis Guerra e Paz, que estão na sede da ONU, em Nova York."], ex: { t: "Mistura das cores", m: "tinta guache vermelha, amarela e azul, pincel, papel, um pote com água", p: ["Pinte três bolinhas: uma vermelha, uma amarela e uma azul.", "Agora misture duas de cada vez: vermelho com amarelo, amarelo com azul, azul com vermelho.", "Que cores nasceram? Com só três cores, dá para pintar um quadro inteiro!"] }, at: "Meu quadro à moda Tarsila", m: "papel grande, guache ou lápis de cor", p: ["Desenhe uma pessoa, um bicho ou uma planta com tamanhos exagerados.", "Use cores fortes e um sol bem redondo no céu.", "Dê um nome inventado ao seu quadro e cole no álbum."], q: "Se você fosse pintar o Brasil num quadro, o que desenharia?" },
en: { h: "Nina drew a person with a giant foot and a tiny head, and Leo laughed at the drawing. Grandpa took out a book and showed them a famous painting that looked a lot like it. “A Brazilian artist painted like this on purpose,” he said. “And the painting became one of the most important in Brazil.”", t: "Brazilian modern art", f: "In 1922, a group of artists held the Modern Art Week in São Paulo. They wanted to create art that looked like Brazil, using bold colors, new shapes and themes from Brazilian life, instead of just copying Europe.", x: "The painting Abaporu, by Tarsila do Amaral in 1928, shows a figure with a huge foot and a small head. Its name comes from Tupi and means something like “man who eats”!", s: ["Tarsila used bright colors, like pink, blue, yellow and green, inspired by the Brazilian countryside.", "Anita Malfatti held an exhibition in 1917 that shocked many people because it was so different.", "Candido Portinari painted workers, children playing and the War and Peace murals, which hang at the United Nations headquarters in New York."], ex: { t: "Color mixing", m: "red, yellow and blue poster paint, a brush, paper, a cup of water", p: ["Paint three dots: one red, one yellow and one blue.", "Now mix two at a time: red with yellow, yellow with blue, blue with red.", "What colors were born? With just three colors, you can paint a whole picture!"] }, at: "My painting, Tarsila-style", m: "large paper, poster paint or colored pencils", p: ["Draw a person, animal or plant with exaggerated sizes.", "Use bold colors and a perfectly round sun in the sky.", "Give your painting a made-up name and glue it into the album."], q: "If you painted Brazil in a picture, what would you draw?" },
es: { h: "Nina dibujó una persona con el pie gigante y la cabeza chiquitita, y Leo se rió del dibujo. El abuelo sacó un libro y les mostró una pintura famosa muy parecida. “Una artista brasileña pintó así a propósito”, dijo. “Y el cuadro se convirtió en uno de los más importantes de Brasil.”", t: "El arte moderno brasileño", f: "En 1922, un grupo de artistas hizo la Semana de Arte Moderno, en São Paulo. Querían crear un arte con cara de Brasil, usando colores fuertes, formas nuevas y temas del pueblo brasileño, en vez de solo copiar a Europa.", x: "¡El cuadro Abaporu, pintado por Tarsila do Amaral en 1928, muestra una figura con un pie enorme y la cabeza pequeña. Su nombre viene del tupí y quiere decir algo como “hombre que come”!", s: ["Tarsila usaba colores vivos, como rosa, azul, amarillo y verde, inspirados en el interior de Brasil.", "Anita Malfatti hizo una exposición en 1917 que asustó a mucha gente por ser tan diferente.", "Candido Portinari pintó trabajadores, niños jugando y los paneles Guerra y Paz, que están en la sede de la ONU, en Nueva York."], ex: { t: "Mezcla de colores", m: "témpera roja, amarilla y azul, pincel, papel, un vaso con agua", p: ["Pinta tres circulitos: uno rojo, uno amarillo y uno azul.", "Ahora mezcla de a dos: rojo con amarillo, amarillo con azul, azul con rojo.", "¿Qué colores nacieron? ¡Con solo tres colores se puede pintar un cuadro entero!"] }, at: "Mi cuadro al estilo Tarsila", m: "papel grande, témpera o lápices de colores", p: ["Dibuja una persona, un animal o una planta con tamaños exagerados.", "Usa colores fuertes y un sol bien redondo en el cielo.", "Ponle un nombre inventado a tu cuadro y pégalo en el álbum."], q: "Si pintaras Brasil en un cuadro, ¿qué dibujarías?" } },

{ e: "🎶", art: { b: "🎸", s: ["🥁", "🪗", "🎶", "🎤"], c: ["#2A0B4E", "#8A2CB0"] },
pt: { h: "O rádio tocou uma música animada, e o vovô tirou Nina para dançar na sala. Depois tocou uma música calminha, de violão, e Leo deitou no sofá. “Tudo isso é música brasileira”, disse o vovô. “Tem música para dançar, para pensar e para matar a saudade.”", t: "O som do Brasil", f: "O Brasil tem muitos ritmos: o samba, o choro, o frevo, o baião, a bossa nova, o forró e muitos outros. Eles misturam tambores africanos, melodias europeias e sons indígenas, e cada região tem o seu jeito de tocar.", x: "A bossa nova Garota de Ipanema, de Tom Jobim e Vinicius de Moraes, é uma das músicas mais gravadas da história no mundo inteiro!", s: ["Pelo Telefone, registrado em 1916, é considerado o primeiro samba gravado em disco.", "Luiz Gonzaga, o Rei do Baião, levou a sanfona e a música do Nordeste para todo o país.", "O frevo, de Pernambuco, é tocado e dançado com sombrinhas coloridas e é Patrimônio Imaterial da Humanidade."], ex: { t: "Xilofone de copos", m: "5 copos de vidro iguais, água, uma colher de metal", p: ["Encha os copos com quantidades diferentes de água, do mais vazio ao mais cheio.", "Bata de leve em cada copo com a colher e escute.", "O copo mais cheio faz som mais grave! Tente tocar uma musiquinha."] }, at: "Pandeiro de pratinhos", m: "dois pratinhos de papel, tampinhas de garrafa, grampeador ou fita, canetinhas", p: ["Enfeite os pratinhos com desenhos coloridos.", "Coloque algumas tampinhas entre eles e grampeie ou cole as bordas.", "Balance e bata: você tem um pandeiro para tocar samba!"], q: "Qual música faz você ter vontade de dançar?" },
en: { h: "The radio played an upbeat song, and Grandpa pulled Nina up to dance in the living room. Then a calm guitar song came on, and Leo lay down on the couch. “All of this is Brazilian music,” Grandpa said. “There's music for dancing, for thinking and for missing someone.”", t: "The sound of Brazil", f: "Brazil has many rhythms: samba, choro, frevo, baião, bossa nova, forró and many more. They mix African drums, European melodies and Indigenous sounds, and every region has its own way of playing.", x: "The bossa nova song The Girl from Ipanema, by Tom Jobim and Vinicius de Moraes, is one of the most recorded songs in history all over the world!", s: ["Pelo Telefone, registered in 1916, is considered the first samba ever recorded.", "Luiz Gonzaga, the King of Baião, brought the accordion and the music of the Northeast to the whole country.", "Frevo, from Pernambuco, is played and danced with colorful little umbrellas and is part of humanity's Intangible Heritage."], ex: { t: "Glass xylophone", m: "5 identical glasses, water, a metal spoon", p: ["Fill the glasses with different amounts of water, from nearly empty to nearly full.", "Tap each glass gently with the spoon and listen.", "The fullest glass makes the lowest sound! Try to play a little tune."] }, at: "Paper plate tambourine", m: "two paper plates, bottle caps, a stapler or tape, markers", p: ["Decorate the plates with colorful drawings.", "Put some bottle caps between them and staple or tape the edges.", "Shake and tap: you have a tambourine for playing samba!"], q: "What song makes you want to dance?" },
es: { h: "La radio pasó una canción animada, y el abuelo sacó a bailar a Nina en la sala. Después sonó una canción tranquila, de guitarra, y Leo se acostó en el sillón. “Todo esto es música brasileña”, dijo el abuelo. “Hay música para bailar, para pensar y para extrañar a alguien.”", t: "El sonido de Brasil", f: "Brasil tiene muchos ritmos: la samba, el choro, el frevo, el baião, la bossa nova, el forró y muchos otros. Mezclan tambores africanos, melodías europeas y sonidos indígenas, y cada región tiene su forma de tocar.", x: "¡La bossa nova Garota de Ipanema, de Tom Jobim y Vinicius de Moraes, es una de las canciones más grabadas de la historia en todo el mundo!", s: ["Pelo Telefone, registrada en 1916, es considerada la primera samba grabada en disco.", "Luiz Gonzaga, el Rey del Baião, llevó el acordeón y la música del Nordeste a todo el país.", "El frevo, de Pernambuco, se toca y se baila con sombrillitas de colores y es Patrimonio Inmaterial de la Humanidad."], ex: { t: "Xilófono de vasos", m: "5 vasos de vidrio iguales, agua, una cuchara de metal", p: ["Llena los vasos con cantidades diferentes de agua, del más vacío al más lleno.", "Golpea suavemente cada vaso con la cuchara y escucha.", "¡El vaso más lleno suena más grave! Intenta tocar una cancioncita."] }, at: "Pandero de platitos", m: "dos platitos de papel, tapitas de botella, abrochadora o cinta, marcadores", p: ["Decora los platitos con dibujos de colores.", "Pon algunas tapitas entre ellos y abrocha o pega los bordes.", "Agítalo y golpéalo: ¡tienes un pandero para tocar samba!"], q: "¿Qué canción te da ganas de bailar?" } },

{ e: "🎉", art: { b: "🎭", s: ["🎉", "🔥", "🐂", "🌽"], c: ["#5A0B3A", "#E02C8A"] },
pt: { h: "Na festa junina da escola, Nina dançou quadrilha de chapéu de palha, e Leo comeu tanta pamonha que ficou com a barriga redonda. O vovô contou que o Brasil é o país das festas. “Tem festa de rua, festa de boi, festa de santo… e o carnaval, claro!”, disse.", t: "As festas do Brasil", f: "O Brasil tem festas populares o ano todo. O carnaval enche as ruas de música e fantasias. As festas juninas celebram a colheita do milho. E o bumba-meu-boi conta a história de um boi que morre e volta à vida, com muita dança e música.", x: "No Festival de Parintins, no Amazonas, dois bois rivais, o Garantido (vermelho) e o Caprichoso (azul), fazem uma disputa de apresentações com milhares de participantes!", s: ["O Complexo Cultural do Bumba-meu-boi do Maranhão é Patrimônio Imaterial da Humanidade desde 2019.", "A quadrilha das festas juninas tem origem numa dança de salão francesa.", "O carnaval de Salvador tem os trios elétricos, caminhões com palco e som que arrastam multidões pelas ruas."], ex: { t: "Milho dançante", m: "um copo transparente, água com gás, alguns grãos de milho de pipoca ou uvas-passas", p: ["Encha o copo com água com gás.", "Jogue os grãos de milho ou as passas dentro.", "Observe: as bolhas grudam nos grãos, eles sobem, as bolhas estouram e eles descem. Os grãos dançam quadrilha!"] }, at: "Bandeirinhas de festa", m: "papel colorido, tesoura, cola, barbante", p: ["Recorte vários triângulos de papel colorido.", "Dobre a parte de cima de cada um sobre o barbante e cole.", "Pendure no quarto e desenhe a sua festa favorita no álbum."], q: "Se você fosse inventar uma festa nova, como ela seria?" },
en: { h: "At the school's June festival, Nina danced the quadrilha in a straw hat, and Leo ate so much pamonha, a sweet corn treat, that his belly got round. Grandpa said Brazil is the land of festivals. “There are street parties, ox festivals, saints' day festivals… and Carnival, of course!” he said.", t: "Brazil's festivals", f: "Brazil has popular festivals all year long. Carnival fills the streets with music and costumes. The June festivals celebrate the corn harvest. And bumba-meu-boi tells the story of an ox that dies and comes back to life, with lots of dancing and music.", x: "At the Parintins Festival in Amazonas, two rival oxen, Garantido (red) and Caprichoso (blue), compete with performances involving thousands of people!", s: ["The Bumba-meu-boi Cultural Complex of Maranhão has been part of humanity's Intangible Heritage since 2019.", "The quadrilha dance of the June festivals comes from a French ballroom dance.", "Salvador's Carnival has trios elétricos, trucks with a stage and speakers that draw huge crowds through the streets."], ex: { t: "Dancing corn", m: "a clear glass, sparkling water, a few popcorn kernels or raisins", p: ["Fill the glass with sparkling water.", "Drop in the kernels or raisins.", "Watch: bubbles stick to them, they float up, the bubbles pop and they sink. The kernels are dancing the quadrilha!"] }, at: "Party flags", m: "colored paper, scissors, glue, string", p: ["Cut out lots of colored paper triangles.", "Fold the top of each one over the string and glue it.", "Hang them in your room and draw your favorite festival in the album."], q: "If you invented a brand-new festival, what would it be like?" },
es: { h: "En la fiesta junina de la escuela, Nina bailó la cuadrilla con sombrero de paja, y Leo comió tanta pamonha, un dulce de maíz, que se le puso la panza redonda. El abuelo contó que Brasil es el país de las fiestas. “Hay fiestas en la calle, fiestas del buey, fiestas de santos… ¡y el carnaval, claro!”, dijo.", t: "Las fiestas de Brasil", f: "Brasil tiene fiestas populares todo el año. El carnaval llena las calles de música y disfraces. Las fiestas juninas celebran la cosecha del maíz. Y el bumba-meu-boi cuenta la historia de un buey que muere y vuelve a la vida, con mucho baile y música.", x: "¡En el Festival de Parintins, en Amazonas, dos bueyes rivales, Garantido (rojo) y Caprichoso (azul), compiten con presentaciones de miles de participantes!", s: ["El Complejo Cultural del Bumba-meu-boi de Maranhão es Patrimonio Inmaterial de la Humanidad desde 2019.", "La cuadrilla de las fiestas juninas tiene origen en un baile de salón francés.", "El carnaval de Salvador tiene los tríos eléctricos, camiones con escenario y sonido que arrastran multitudes por las calles."], ex: { t: "Maíz que baila", m: "un vaso transparente, agua con gas, algunos granos de maíz pisingallo o pasas de uva", p: ["Llena el vaso con agua con gas.", "Echa adentro los granos de maíz o las pasas.", "Observa: las burbujas se pegan a los granos, suben, las burbujas revientan y bajan. ¡Los granos bailan la cuadrilla!"] }, at: "Banderines de fiesta", m: "papel de colores, tijera, pegamento, cordel", p: ["Recorta muchos triángulos de papel de colores.", "Dobla la parte de arriba de cada uno sobre el cordel y pégala.", "Cuélgalos en tu cuarto y dibuja tu fiesta favorita en el álbum."], q: "Si inventaras una fiesta nueva, ¿cómo sería?" } },

{ e: "⚽", art: { b: "⚽", s: ["🏆", "🥅", "👟", "🏟️"], c: ["#0B4F2C", "#D4C02C"] },
pt: { h: "Leo chutou a bola no quintal e gritou “gooool!” tão alto que o Pipoca pulou do muro. Nina, que é a melhor goleira da turma, defendeu o próximo chute. O vovô aplaudiu os dois e perguntou: “Sabem quem trouxe a primeira bola de futebol para o Brasil?”", t: "O país do futebol", f: "O futebol chegou ao Brasil em 1894, quando Charles Miller voltou de seus estudos na Inglaterra com duas bolas na mala. O esporte se espalhou pelo país e virou uma paixão: o Brasil é o único país pentacampeão da Copa do Mundo masculina.", x: "Marta, da seleção brasileira, foi eleita seis vezes a melhor jogadora do mundo pela FIFA, um recorde entre as jogadoras!", s: ["O Brasil ganhou as Copas de 1958, 1962, 1970, 1994 e 2002.", "Pelé é o único jogador a ter ganhado três Copas do Mundo.", "Durante muitos anos, as mulheres foram proibidas por lei de jogar futebol no Brasil, mas elas continuaram lutando para jogar."], ex: { t: "Quique da bola", m: "uma bola que dá para encher, uma bomba de ar, uma fita métrica, um ajudante", p: ["Com a bola meio murcha, solte-a sempre da mesma altura e meça até onde ela quica.", "Agora encha bem a bola e solte da mesma altura.", "Ela quica muito mais alto! O ar apertado lá dentro funciona como uma mola."] }, at: "Uniforme do meu time", m: "papel, lápis de cor", p: ["Invente um time com nome, cores e mascote.", "Desenhe a camisa, o calção e o escudo.", "Cole no álbum e escolha quem da família seria o técnico!"], q: "Qual esporte você mais gosta de jogar? Por quê?" },
en: { h: "Leo kicked the ball in the backyard and yelled “gooooal!” so loudly that Popcorn jumped off the wall. Nina, the best goalkeeper in her class, blocked the next shot. Grandpa clapped for both of them and asked, “Do you know who brought the first soccer ball to Brazil?”", t: "The land of soccer", f: "Soccer reached Brazil in 1894, when Charles Miller came back from studying in England with two balls in his suitcase. The sport spread across the country and became a passion: Brazil is the only five-time winner of the men's World Cup.", x: "Marta, of Brazil's national team, was named the world's best player by FIFA six times, a record among women players!", s: ["Brazil won the World Cups of 1958, 1962, 1970, 1994 and 2002.", "Pelé is the only player to have won three World Cups.", "For many years, women were banned by law from playing soccer in Brazil, but they kept fighting to play."], ex: { t: "Ball bounce", m: "an inflatable ball, an air pump, a tape measure, a helper", p: ["With the ball half flat, drop it from the same height each time and measure how high it bounces.", "Now pump the ball up well and drop it from the same height.", "It bounces much higher! The squeezed air inside works like a spring."] }, at: "My team's uniform", m: "paper, colored pencils", p: ["Invent a team with a name, colors and a mascot.", "Draw the jersey, shorts and crest.", "Glue it into the album and choose who in the family would be the coach!"], q: "What sport do you like playing most? Why?" },
es: { h: "Leo pateó la pelota en el patio y gritó “¡gooool!” tan fuerte que Palomita saltó del muro. Nina, la mejor arquera de su clase, atajó el siguiente tiro. El abuelo aplaudió a los dos y preguntó: “¿Saben quién trajo la primera pelota de fútbol a Brasil?”", t: "El país del fútbol", f: "El fútbol llegó a Brasil en 1894, cuando Charles Miller volvió de estudiar en Inglaterra con dos pelotas en la maleta. El deporte se extendió por el país y se volvió una pasión: Brasil es el único país pentacampeón de la Copa del Mundo masculina.", x: "¡Marta, de la selección brasileña, fue elegida seis veces la mejor jugadora del mundo por la FIFA, un récord entre las jugadoras!", s: ["Brasil ganó las Copas de 1958, 1962, 1970, 1994 y 2002.", "Pelé es el único jugador que ganó tres Copas del Mundo.", "Durante muchos años, a las mujeres se les prohibió por ley jugar al fútbol en Brasil, pero siguieron luchando para jugar."], ex: { t: "El rebote de la pelota", m: "una pelota que se pueda inflar, un inflador, una cinta métrica, un ayudante", p: ["Con la pelota medio desinflada, suéltala siempre desde la misma altura y mide cuánto rebota.", "Ahora ínflala bien y suéltala desde la misma altura.", "¡Rebota mucho más alto! El aire apretado adentro funciona como un resorte."] }, at: "El uniforme de mi equipo", m: "papel, lápices de colores", p: ["Inventa un equipo con nombre, colores y mascota.", "Dibuja la camiseta, el short y el escudo.", "¡Pégalo en el álbum y elige quién de la familia sería el entrenador!"], q: "¿Qué deporte te gusta más jugar? ¿Por qué?" } },

{ e: "🏛️", art: { b: "🏛️", s: ["✈️", "🏗️", "🌅", "📐"], c: ["#0B2A4E", "#2C6AB0"] },
pt: { h: "Leo montou uma cidade inteira de blocos no chão da sala. O vovô olhou de cima e disse: “Sabia que existe uma cidade brasileira que, vista do céu, parece um avião?”. Nina achou que era brincadeira, até ver a foto de Brasília.", t: "Brasília: a capital no meio do Brasil", f: "Em 1960, a capital do Brasil saiu do Rio de Janeiro e foi para Brasília, uma cidade nova construída no centro do país. A ideia era levar desenvolvimento para o interior. O presidente da época, Juscelino Kubitschek, fez a cidade ser construída em pouco mais de três anos.", x: "Vista de cima, a parte principal de Brasília tem forma de avião (ou de pássaro)! O desenho foi feito pelo urbanista Lúcio Costa, e os prédios curvos pelo arquiteto Oscar Niemeyer.", s: ["Brasília foi inaugurada em 21 de abril de 1960.", "A cidade é Patrimônio Mundial da UNESCO desde 1987.", "Milhares de trabalhadores, vindos principalmente do Nordeste, construíram a cidade. Eles foram chamados de candangos."], ex: { t: "Colunas de papel", m: "3 folhas de papel, fita adesiva, livros", p: ["Faça três colunas com as folhas: uma em formato de cilindro, uma de triângulo e uma de quadrado, e prenda com fita.", "Coloque cada coluna em pé e vá empilhando livros em cima, com cuidado.", "Qual aguentou mais? O cilindro costuma vencer! Por isso tantas construções usam colunas redondas."] }, at: "Cidade vista do céu", m: "papel grande, lápis de cor", p: ["Desenhe uma cidade inventada vista de cima, como um passarinho veria.", "Dê a ela uma forma especial: estrela, coração, peixe ou o que você quiser.", "Marque onde ficam as casas, as praças, as escolas e os parques, e cole no álbum."], q: "Se você fosse construir uma cidade nova, onde ela ficaria e como seria?" },
en: { h: "Leo built a whole city out of blocks on the living room floor. Grandpa looked down at it and said, “Did you know there's a Brazilian city that looks like an airplane from the sky?” Nina thought he was joking until she saw a photo of Brasília.", t: "Brasília: the capital in the middle of Brazil", f: "In 1960, Brazil's capital moved from Rio de Janeiro to Brasília, a brand-new city built in the center of the country. The idea was to bring development inland. The president at the time, Juscelino Kubitschek, had the city built in just over three years.", x: "Seen from above, the main part of Brasília is shaped like an airplane (or a bird)! The plan was designed by urban planner Lúcio Costa, and the curvy buildings by architect Oscar Niemeyer.", s: ["Brasília was inaugurated on April 21, 1960.", "The city has been a UNESCO World Heritage Site since 1987.", "Thousands of workers, mostly from the Northeast, built the city. They were called candangos."], ex: { t: "Paper columns", m: "3 sheets of paper, tape, books", p: ["Make three columns from the sheets: one shaped like a cylinder, one like a triangle and one like a square, and tape them.", "Stand each column up and carefully stack books on top.", "Which held the most? The cylinder usually wins! That's why so many buildings use round columns."] }, at: "City from the sky", m: "large paper, colored pencils", p: ["Draw an invented city seen from above, the way a bird would see it.", "Give it a special shape: a star, a heart, a fish or anything you like.", "Mark where the houses, squares, schools and parks are, and glue it into the album."], q: "If you built a new city, where would it be and what would it be like?" },
es: { h: "Leo armó una ciudad entera de bloques en el piso de la sala. El abuelo la miró desde arriba y dijo: “¿Sabías que hay una ciudad brasileña que, vista desde el cielo, parece un avión?”. Nina creyó que era una broma, hasta que vio la foto de Brasilia.", t: "Brasilia: la capital en el medio de Brasil", f: "En 1960, la capital de Brasil pasó de Río de Janeiro a Brasilia, una ciudad nueva construida en el centro del país. La idea era llevar desarrollo al interior. El presidente de la época, Juscelino Kubitschek, hizo construir la ciudad en poco más de tres años.", x: "¡Vista desde arriba, la parte principal de Brasilia tiene forma de avión (o de pájaro)! El plano lo hizo el urbanista Lúcio Costa, y los edificios curvos el arquitecto Oscar Niemeyer.", s: ["Brasilia se inauguró el 21 de abril de 1960.", "La ciudad es Patrimonio Mundial de la UNESCO desde 1987.", "Miles de trabajadores, venidos sobre todo del Nordeste, construyeron la ciudad. Los llamaron candangos."], ex: { t: "Columnas de papel", m: "3 hojas de papel, cinta adhesiva, libros", p: ["Haz tres columnas con las hojas: una en forma de cilindro, una de triángulo y una de cuadrado, y sujétalas con cinta.", "Pon cada columna de pie y ve apilando libros encima, con cuidado.", "¿Cuál aguantó más? ¡El cilindro suele ganar! Por eso tantas construcciones usan columnas redondas."] }, at: "Ciudad vista desde el cielo", m: "papel grande, lápices de colores", p: ["Dibuja una ciudad inventada vista desde arriba, como la vería un pájaro.", "Dale una forma especial: estrella, corazón, pez o lo que quieras.", "Marca dónde están las casas, las plazas, las escuelas y los parques, y pégala en el álbum."], q: "Si construyeras una ciudad nueva, ¿dónde estaría y cómo sería?" } },

{ e: "🗳️", art: { b: "🗳️", s: ["📜", "🤝", "🗣️", "✅"], c: ["#1B2A4E", "#4A6AB0"] },
pt: { h: "Na hora de escolher o filme da noite, todo mundo queria um diferente. Nina teve uma ideia: “Vamos votar!”. Cada um escreveu sua escolha num papelzinho e colocou numa caixa. O vovô sorriu: “Vocês acabaram de fazer o que um país inteiro faz numa eleição.”", t: "Democracia: o povo escolhe", f: "Democracia é quando as pessoas escolhem seus governantes pelo voto e têm direitos garantidos. No Brasil, entre 1964 e 1985, houve um período em que o povo não podia votar para presidente. Muitas pessoas lutaram, e a democracia voltou.", x: "A Constituição de 1988, a lei mais importante do Brasil, é chamada de Constituição Cidadã, porque garante muitos direitos, como saúde, educação e proteção às crianças!", s: ["As mulheres conquistaram o direito de votar no Brasil em 1932, depois da luta de pessoas como a cientista Bertha Lutz.", "Em 1984, milhões de pessoas foram às ruas no movimento Diretas Já, pedindo para votar para presidente.", "O Brasil usa urnas eletrônicas nas eleições desde 1996."], ex: { t: "Eleição secreta em casa", m: "uma caixa de sapato com uma fenda, papeizinhos, lápis", p: ["Escolham algo para votar: o lanche de amanhã ou o jogo da noite. Façam 2 ou 3 opções.", "Cada pessoa vota em segredo e coloca o papel na caixa.", "Abram a caixa, contem os votos em voz alta e anotem: a opção mais votada vence. Todos respeitam o resultado!"] }, at: "A constituição da nossa casa", m: "papel grande, lápis de cor", p: ["Conversem em família sobre as regras e os direitos de cada um em casa.", "Escrevam 5 regras justas e 5 direitos, como “todos podem dar opinião”.", "Todos assinam embaixo, e uma cópia vai para o álbum."], q: "Por que é importante que todos possam dar sua opinião?" },
en: { h: "When it was time to choose the movie for the night, everyone wanted a different one. Nina had an idea: “Let's vote!” Each person wrote their choice on a slip of paper and put it in a box. Grandpa smiled: “You just did what a whole country does in an election.”", t: "Democracy: the people choose", f: "Democracy is when people choose their leaders by voting and have guaranteed rights. In Brazil, between 1964 and 1985, there was a period when people couldn't vote for president. Many people struggled, and democracy came back.", x: "The Constitution of 1988, Brazil's most important law, is called the Citizen Constitution because it guarantees many rights, like health care, education and protection for children!", s: ["Women won the right to vote in Brazil in 1932, after the efforts of people like the scientist Bertha Lutz.", "In 1984, millions of people took to the streets in the Diretas Já movement, asking to vote for president.", "Brazil has used electronic voting machines in elections since 1996."], ex: { t: "Secret ballot at home", m: "a shoebox with a slot, slips of paper, pencils", p: ["Pick something to vote on: tomorrow's snack or tonight's game. Make 2 or 3 options.", "Each person votes in secret and drops the paper in the box.", "Open the box, count the votes out loud and write them down: the option with the most votes wins. Everyone respects the result!"] }, at: "Our home constitution", m: "large paper, colored pencils", p: ["Talk as a family about the rules and rights of each person at home.", "Write 5 fair rules and 5 rights, like “everyone can share their opinion.”", "Everyone signs at the bottom, and a copy goes in the album."], q: "Why is it important for everyone to be able to share their opinion?" },
es: { h: "A la hora de elegir la película de la noche, cada uno quería una diferente. Nina tuvo una idea: “¡Votemos!”. Cada uno escribió su elección en un papelito y lo puso en una caja. El abuelo sonrió: “Acaban de hacer lo que hace un país entero en una elección.”", t: "Democracia: el pueblo elige", f: "Democracia es cuando las personas eligen a sus gobernantes con el voto y tienen derechos garantizados. En Brasil, entre 1964 y 1985, hubo un período en que el pueblo no podía votar para presidente. Mucha gente luchó, y la democracia volvió.", x: "¡La Constitución de 1988, la ley más importante de Brasil, se llama Constitución Ciudadana porque garantiza muchos derechos, como la salud, la educación y la protección de los niños!", s: ["Las mujeres conquistaron el derecho a votar en Brasil en 1932, después de la lucha de personas como la científica Bertha Lutz.", "En 1984, millones de personas salieron a las calles en el movimiento Diretas Já, pidiendo votar para presidente.", "Brasil usa urnas electrónicas en las elecciones desde 1996."], ex: { t: "Elección secreta en casa", m: "una caja de zapatos con una ranura, papelitos, lápices", p: ["Elijan algo para votar: la merienda de mañana o el juego de la noche. Hagan 2 o 3 opciones.", "Cada persona vota en secreto y pone el papel en la caja.", "Abran la caja, cuenten los votos en voz alta y anótenlos: gana la opción más votada. ¡Todos respetan el resultado!"] }, at: "La constitución de nuestra casa", m: "papel grande, lápices de colores", p: ["Conversen en familia sobre las reglas y los derechos de cada uno en casa.", "Escriban 5 reglas justas y 5 derechos, como “todos pueden dar su opinión”.", "Todos firman abajo, y una copia va al álbum."], q: "¿Por qué es importante que todos puedan dar su opinión?" } },

{ e: "🌿", art: { b: "🌿", s: ["🐆", "🦜", "🐊", "🌊"], c: ["#0B4F1B", "#2CA03A"] },
pt: { h: "O vovô colocou um saquinho plástico em volta de um galho da planta da varanda e prendeu com barbante. No fim da tarde, o saquinho estava cheio de gotinhas. “De onde veio essa água?”, perguntou Leo. “Da planta!”, respondeu o vovô. “E na Amazônia isso acontece com bilhões de árvores.”", t: "A natureza do Brasil", f: "O Brasil é o país com mais espécies de plantas e animais do mundo. Aqui ficam a maior parte da Floresta Amazônica, a maior floresta tropical do planeta, o Pantanal, uma das maiores áreas alagadas do mundo, a Mata Atlântica, o Cerrado, a Caatinga e os Pampas.", x: "As árvores da Amazônia soltam tanta água no ar que formam “rios voadores”, nuvens de vapor que levam chuva para outras partes do Brasil!", s: ["Cerca de 60% da Floresta Amazônica fica no Brasil.", "A onça-pintada é o maior felino das Américas e vive em vários biomas brasileiros.", "O mico-leão-dourado quase desapareceu, mas foi salvo graças a muito trabalho de proteção da Mata Atlântica."], ex: { t: "Rio voador no saquinho", m: "um saco plástico transparente, barbante, uma planta com folhas (no vaso ou no jardim), sol", p: ["Coloque o saco em volta de um galho com folhas e amarre com cuidado, sem apertar demais.", "Deixe a planta no sol por algumas horas.", "Veja as gotinhas dentro do saco: é a água que as folhas soltam! Depois, tire o saco para a planta respirar."] }, at: "Mapa dos biomas", m: "papel, lápis de cor, um mapa do Brasil", p: ["Desenhe o contorno do Brasil.", "Pinte cada bioma de uma cor: Amazônia, Cerrado, Caatinga, Mata Atlântica, Pantanal e Pampa.", "Desenhe um animal de cada bioma e cole no álbum."], q: "Que animal brasileiro você gostaria de proteger? Como?" },
en: { h: "Grandpa put a little plastic bag around a branch of the balcony plant and tied it with string. By late afternoon, the bag was full of droplets. “Where did that water come from?” asked Leo. “From the plant!” Grandpa answered. “And in the Amazon, this happens with billions of trees.”", t: "Brazil's nature", f: "Brazil has more species of plants and animals than any other country in the world. It holds most of the Amazon Rainforest, the largest tropical forest on the planet, plus the Pantanal, one of the world's largest wetlands, the Atlantic Forest, the Cerrado, the Caatinga and the Pampas.", x: "The Amazon's trees release so much water into the air that they form “flying rivers,” clouds of vapor that carry rain to other parts of Brazil!", s: ["About 60% of the Amazon Rainforest is in Brazil.", "The jaguar is the largest cat in the Americas and lives in several Brazilian biomes.", "The golden lion tamarin almost disappeared, but it was saved thanks to lots of work protecting the Atlantic Forest."], ex: { t: "Flying river in a bag", m: "a clear plastic bag, string, a leafy plant (in a pot or garden), sunshine", p: ["Put the bag around a leafy branch and tie it gently, not too tight.", "Leave the plant in the sun for a few hours.", "Look at the droplets inside the bag: it's water the leaves give off! Afterwards, remove the bag so the plant can breathe."] }, at: "Biome map", m: "paper, colored pencils, a map of Brazil", p: ["Draw the outline of Brazil.", "Color each biome differently: Amazon, Cerrado, Caatinga, Atlantic Forest, Pantanal and Pampa.", "Draw an animal from each biome and glue it into the album."], q: "Which Brazilian animal would you like to protect? How?" },
es: { h: "El abuelo puso una bolsita de plástico alrededor de una rama de la planta del balcón y la ató con cordel. Al final de la tarde, la bolsita estaba llena de gotitas. “¿De dónde salió esa agua?”, preguntó Leo. “¡De la planta!”, respondió el abuelo. “Y en la Amazonía eso pasa con miles de millones de árboles.”", t: "La naturaleza de Brasil", f: "Brasil es el país con más especies de plantas y animales del mundo. Aquí está la mayor parte de la Selva Amazónica, el bosque tropical más grande del planeta, además del Pantanal, uno de los humedales más grandes del mundo, la Mata Atlántica, el Cerrado, la Caatinga y la Pampa.", x: "¡Los árboles de la Amazonía sueltan tanta agua al aire que forman “ríos voladores”, nubes de vapor que llevan lluvia a otras partes de Brasil!", s: ["Cerca del 60% de la Selva Amazónica está en Brasil.", "El jaguar es el felino más grande de América y vive en varios biomas brasileños.", "El tití león dorado casi desapareció, pero se salvó gracias a mucho trabajo de protección de la Mata Atlántica."], ex: { t: "Río volador en la bolsita", m: "una bolsa de plástico transparente, cordel, una planta con hojas (en maceta o en el jardín), sol", p: ["Pon la bolsa alrededor de una rama con hojas y átala con cuidado, sin apretar mucho.", "Deja la planta al sol unas horas.", "Mira las gotitas dentro de la bolsa: ¡es el agua que sueltan las hojas! Después, quita la bolsa para que la planta respire."] }, at: "Mapa de los biomas", m: "papel, lápices de colores, un mapa de Brasil", p: ["Dibuja el contorno de Brasil.", "Pinta cada bioma de un color: Amazonía, Cerrado, Caatinga, Mata Atlántica, Pantanal y Pampa.", "Dibuja un animal de cada bioma y pégalo en el álbum."], q: "¿Qué animal brasileño te gustaría proteger? ¿Cómo?" } },

{ e: "🍲", art: { b: "🍲", s: ["🧀", "🥥", "🧉", "🌶️"], c: ["#5A3A0B", "#D4802C"] },
pt: { h: "Uma prima do vovô veio do Pará e trouxe tacacá, uma tia da Bahia mandou um vidro de pimenta, e um amigo gaúcho ensinou Leo a segurar a cuia de chimarrão. “Parece que cada lugar do Brasil é um país diferente”, disse Nina. “É um país só, mas com muitos jeitos”, respondeu o vovô.", t: "Um Brasil, muitos Brasis", f: "O Brasil tem 26 estados e o Distrito Federal, divididos em cinco regiões: Norte, Nordeste, Centro-Oeste, Sudeste e Sul. Cada região tem seu sotaque, suas comidas, suas músicas e suas festas.", x: "Mais de 200 milhões de pessoas moram no Brasil, e todas falam português, mas com sotaques e palavras diferentes: a mesma fruta pode se chamar mexerica, tangerina ou bergamota, dependendo de onde você está!", s: ["No Norte, são famosos o tacacá e o açaí, comido com farinha ou peixe.", "O acarajé, na Bahia, o pão de queijo, em Minas, e o chimarrão, no Sul, são tradições muito queridas.", "No Centro-Oeste, o pequi é um fruto típico do Cerrado, mas cuidado: ele tem espinhos por dentro!"], ex: { t: "Tapioca mágica", m: "goma de tapioca hidratada (vende pronta), uma frigideira antiaderente, uma peneira, um adulto no fogão", p: ["Com um adulto, peneire a goma na frigideira fria, formando um círculo fininho.", "O adulto liga o fogo baixo: em pouco tempo os grãozinhos de amido grudam uns nos outros com o calor.", "Vira uma panqueca inteira, sem ovo e sem leite! Recheie com o que gostar quando esfriar um pouco."] }, at: "Mapa dos sabores", m: "papel, lápis de cor", p: ["Desenhe o Brasil dividido nas cinco regiões.", "Em cada região, desenhe uma comida típica.", "Marque com um coração as que você já provou e cole no álbum."], q: "Qual comida de outra região do Brasil você gostaria de provar?" },
en: { h: "A cousin of Grandpa's came from Pará and brought tacacá soup, an aunt from Bahia sent a jar of hot peppers, and a friend from the South taught Leo how to hold a chimarrão gourd. “It's like every part of Brazil is a different country,” Nina said. “It's one country, but with many ways of being,” Grandpa answered.", t: "One Brazil, many Brazils", f: "Brazil has 26 states and the Federal District, divided into five regions: North, Northeast, Central-West, Southeast and South. Each region has its own accent, foods, music and festivals.", x: "More than 200 million people live in Brazil, and they all speak Portuguese, but with different accents and words: the same fruit, a tangerine, can be called mexerica, tangerina or bergamota depending on where you are!", s: ["In the North, tacacá and açaí, eaten with cassava flour or fish, are famous.", "Acarajé in Bahia, pão de queijo (cheese bread) in Minas Gerais and chimarrão (a hot herbal drink) in the South are much-loved traditions.", "In the Central-West, pequi is a typical fruit of the Cerrado, but careful: it has spines inside!"], ex: { t: "Magic tapioca", m: "hydrated tapioca starch (sold ready to use), a nonstick pan, a sieve, a grown-up at the stove", p: ["With a grown-up, sift the starch into the cold pan, making a thin circle.", "The grown-up turns on low heat: soon the tiny starch grains stick together with the heat.", "It becomes a whole pancake, with no eggs or milk! Fill it with whatever you like once it cools a bit."] }, at: "Map of flavors", m: "paper, colored pencils", p: ["Draw Brazil divided into its five regions.", "In each region, draw a typical food.", "Put a heart on the ones you've tried and glue it into the album."], q: "Which food from another region would you like to try?" },
es: { h: "Una prima del abuelo vino de Pará y trajo tacacá, una tía de Bahía mandó un frasco de ají, y un amigo del Sur le enseñó a Leo a sostener el mate de chimarrão. “Parece que cada lugar de Brasil es un país distinto”, dijo Nina. “Es un solo país, pero con muchas formas de ser”, respondió el abuelo.", t: "Un Brasil, muchos Brasiles", f: "Brasil tiene 26 estados y el Distrito Federal, divididos en cinco regiones: Norte, Nordeste, Centro-Oeste, Sudeste y Sur. Cada región tiene su acento, sus comidas, sus músicas y sus fiestas.", x: "¡Más de 200 millones de personas viven en Brasil, y todas hablan portugués, pero con acentos y palabras diferentes: la misma mandarina puede llamarse mexerica, tangerina o bergamota, según dónde estés!", s: ["En el Norte son famosos el tacacá y el açaí, que se come con harina de mandioca o pescado.", "El acarajé en Bahía, el pão de queijo (pan de queso) en Minas Gerais y el chimarrão (mate) en el Sur son tradiciones muy queridas.", "En el Centro-Oeste, el pequi es un fruto típico del Cerrado, pero cuidado: ¡tiene espinitas por dentro!"], ex: { t: "Tapioca mágica", m: "almidón de tapioca hidratado (se vende listo), una sartén antiadherente, un colador, un adulto en la cocina", p: ["Con un adulto, tamiza el almidón sobre la sartén fría, formando un círculo finito.", "El adulto enciende el fuego bajo: enseguida los granitos de almidón se pegan unos a otros con el calor.", "¡Se forma un panqueque entero, sin huevo ni leche! Rellénalo con lo que te guste cuando se enfríe un poco."] }, at: "Mapa de sabores", m: "papel, lápices de colores", p: ["Dibuja Brasil dividido en sus cinco regiones.", "En cada región, dibuja una comida típica.", "Marca con un corazón las que ya probaste y pégalo en el álbum."], q: "¿Qué comida de otra región de Brasil te gustaría probar?" } },

{ e: "🏅", art: { b: "📖", s: ["🦜", "⭐", "🌳", "🎉"], c: ["#0B4F2C", "#D4B02C"] },
pt: { h: "Na última noite, Nina e Leo colaram a figurinha que faltava, e o Álbum do Brasil ficou completo. Os dois folhearam tudo, desde a aldeia de palitos até o mapa dos sabores. O vovô fechou o álbum com cuidado e disse: “Agora falta só uma página. E essa quem vai escrever são vocês.”", t: "O Brasil de hoje e de amanhã", f: "A história do Brasil foi feita por muitos povos: indígenas, africanos, europeus, asiáticos e tantos outros. Ela tem partes bonitas e partes difíceis, e ainda está sendo escrita, todos os dias, por cada pessoa que vive aqui.", x: "Você também faz parte da história do Brasil! Daqui a muitos anos, crianças vão estudar sobre o tempo em que você é criança.", s: ["Cuidar da natureza, respeitar as diferenças e estudar são jeitos de construir um país melhor.", "O Brasil é diverso: tem gente de todas as cores, religiões, sotaques e jeitos de viver.", "Conhecer a história ajuda a entender o presente e a imaginar o futuro."], ex: { t: "Tinta da terra brasileira", m: "açafrão-da-terra, café em pó, beterraba ralada, folhas de espinafre amassadas, potinhos com um pouquinho de água, pincel, papel", p: ["Com um adulto, misture cada ingrediente com um pouquinho de água em um potinho diferente.", "Você terá amarelo, marrom, vermelho e verde, todos naturais!", "Use essas tintas para pintar o contorno do Brasil na última página do álbum."] }, at: "A capa do meu álbum", m: "papel grande, lápis de cor, as figurinhas que você fez", p: ["Desenhe uma capa para o seu Álbum do Brasil com seu nome.", "Escolha as três figurinhas de que mais gostou e explique por quê.", "Apresente o álbum para a família, como um guia de museu!"], q: "O que você gostaria que as crianças do futuro aprendessem sobre o Brasil de hoje?" },
en: { h: "On the last night, Nina and Leo glued in the final sticker, and the Brazil Album was complete. They flipped through everything, from the popsicle-stick village to the map of flavors. Grandpa closed the album carefully and said, “Now there's only one page left. And you two are the ones who'll write it.”", t: "The Brazil of today and tomorrow", f: "Brazil's history was made by many peoples: Indigenous, African, European, Asian and so many others. It has beautiful parts and hard parts, and it's still being written every day by everyone who lives there.", x: "You are part of history too! Many years from now, kids will study the time when you were a kid.", s: ["Caring for nature, respecting differences and learning are ways to build a better country.", "Brazil is diverse: it has people of every color, religion, accent and way of life.", "Knowing history helps us understand the present and imagine the future."], ex: { t: "Paint from Brazilian earth", m: "turmeric, ground coffee, grated beet, crushed spinach leaves, small cups with a little water, a brush, paper", p: ["With a grown-up, mix each ingredient with a little water in a separate cup.", "You'll have yellow, brown, red and green, all natural!", "Use these paints to color the outline of Brazil on the last page of the album."] }, at: "My album cover", m: "large paper, colored pencils, the stickers you made", p: ["Draw a cover for your Brazil Album with your name on it.", "Pick the three stickers you liked best and explain why.", "Present the album to your family, like a museum guide!"], q: "What would you want kids in the future to learn about the world today?" },
es: { h: "En la última noche, Nina y Leo pegaron la figurita que faltaba, y el Álbum de Brasil quedó completo. Los dos lo hojearon todo, desde la aldea de palitos hasta el mapa de sabores. El abuelo cerró el álbum con cuidado y dijo: “Ahora falta solo una página. Y esa la van a escribir ustedes.”", t: "El Brasil de hoy y de mañana", f: "La historia de Brasil la hicieron muchos pueblos: indígenas, africanos, europeos, asiáticos y tantos otros. Tiene partes lindas y partes difíciles, y todavía se está escribiendo, todos los días, por cada persona que vive allí.", x: "¡Tú también eres parte de la historia! Dentro de muchos años, otros niños van a estudiar la época en que tú eras niño.", s: ["Cuidar la naturaleza, respetar las diferencias y estudiar son formas de construir un país mejor.", "Brasil es diverso: tiene gente de todos los colores, religiones, acentos y formas de vivir.", "Conocer la historia ayuda a entender el presente y a imaginar el futuro."], ex: { t: "Pintura de tierra brasileña", m: "cúrcuma, café molido, remolacha rallada, hojas de espinaca machacadas, potecitos con un poquito de agua, pincel, papel", p: ["Con un adulto, mezcla cada ingrediente con un poquito de agua en un potecito diferente.", "¡Tendrás amarillo, marrón, rojo y verde, todos naturales!", "Usa esas pinturas para pintar el contorno de Brasil en la última página del álbum."] }, at: "La tapa de mi álbum", m: "papel grande, lápices de colores, las figuritas que hiciste", p: ["Dibuja una tapa para tu Álbum de Brasil con tu nombre.", "Elige las tres figuritas que más te gustaron y explica por qué.", "¡Presenta el álbum a tu familia, como un guía de museo!"], q: "¿Qué te gustaría que los niños del futuro aprendieran sobre el mundo de hoy?" } },
];
